956	  c.addEventListener('click',function(){toggleOv(false);goTo(i,i<idx);}); ovg.appendChild(c);
957	});
958	function update(){
959	  counter.textContent=(idx+1)+' / '+TOTAL;
960	  pbar.style.width=(idx/(TOTAL-1)*100)+'%';
961	  [].forEach.call(dotsBox.children,function(d,i){d.classList.toggle('on',i===idx);});
