964	  var onLight=s.dataset.theme==='light' && root.dataset.themeMode!=='dark';
965	  brand.classList.toggle('on-light',onLight);
966	  if (FIELD) FIELD.setMode(s.dataset.theme==='dark' || root.dataset.themeMode==='dark', !!s.dataset.divider || s.classList.contains('t-cover'));
